let candleCache={},lastMonth='',runSource='';
function testSources(){return [...imports.filter(f=>f.minute).map(f=>({id:f.id,s:f.s,title:f.s+' · '+f.src+' · '+f.name,data:f})),...all.map(s=>({id:'demo:'+s,s,title:s+' · Demo minute candles'}))]}
let contractMode="Equity",optionSide="CE";
function backtester(){let sources=testSources(),src=sources.find(x=>x.id===chosen)||sources[imports.filter(f=>f.minute).length];$('app').innerHTML=heading('Strategy research','Backtester','Test entries, exits and risk rules against one-minute OHLC candles.','<div class="actions">'+importButton+'<button onclick="strategyLibrary()">Saved strategies</button></div>')+'<form class="panel" id="builder"><h2>Backtest period</h2><div class="fields">'+select('Dates','bp',presetNames)+input('From date','bf',start,'date')+input('To date','bt',end,'date')+'</div><div class="row divider"><h2>Instrument</h2><span class="tag">1 minute · IST</span></div><div class="instrumentTools">'+select('Instrument type','contractMode',['Equity','Options','Future'])+select('Contract side','optionSide',['CE','PE'])+'</div><div id="contractFields" hidden class="fields">'+select('Trade type','holding',['Intraday','Positional'])+select('Entry condition','entryRule',['Time only','Strike price','Premium above','Premium below','Premium near','Spot above','Future above','Delta above','Delta below','Indicator above'])+input('Rule value','ruleValue',0,'number','step="any"')+input('Near tolerance ₹','tolerance',1,'number','min="0" step="any"')+'<label>Expiry<input id="expiry" type="date"></label><label>Strike price<input id="strike" readonly></label><label>Entry day<select id="dte"><option value="">Every eligible session</option>'+Array.from({length:31},(_,i)=>'<option value="'+i+'">'+i+' calendar days before expiry</option>').join('')+'</select></label></div><div id="liveSearch" aria-live="polite"></div><div id="contractNote" class="hint"></div><div class="fields"><label>Search instrument<input id="searchInstrument" type="search" placeholder="Name or symbol" autocomplete="off"></label><label>Instrument<select id="feed">'+sources.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.title)+'</option>').join('')+'</select></label>'+select('Direction','action',['Buy','Sell'])+input('Lots / quantity','lots',1,'number','min="1"')+input('Units per lot','units',1,'number','min="1"')+'</div><h3 class="divider">Session timing</h3><div class="fields">'+input('Entry time','et','09:30','time')+input('Exit time','xt','15:15','time')+'</div><h3 class="divider">Risk &amp; execution costs</h3><div class="fields">'+riskField('Target','tp','targetUnit',1)+riskField('Stop loss','sl','stopUnit',0.6)+[['Trailing stop %','tr',0],['Slippage bps / fill','slip',0]].map(([l,id,v])=>input(l,id,v,'number','min="0" max="9999" step="any"')).join('')+'</div><div class="row"><button type="button" onclick="chargesPanel()">Charges &amp; taxes</button><span id="feeSummary" class="hint">Review configured charges before running</span><span class="hint" id="coverage"></span><button class="primary">Run backtest</button></div><details><summary>Execution assumptions &amp; data gaps</summary>One position at a time. Intraday trades close the same session. Positional options exit the next observed session unless a risk exit occurs earlier. Overnight runs require complete regular-session candles through 15:29 and from 09:15 on the exit day. Entry and timed exit use the specified candle opens. All one-minute candles between those times must be present or the session is skipped. Entirely absent dates produce no trades. A gap through a stop or target fills at the new open. Within a candle the stop wins a stop/target tie. Trailing levels tighten after a completed candle and apply to the next candle. Slippage is adverse on both fills. Fees apply to each fill and both turnovers. Drawdown uses realized net equity at trade closes. Options require imported prices for the exact contract. A zero risk percentage disables that rule.</details></form><div id="results"></div>';$('feed').value=src.id;function sourceChanged(){src=sources.find(x=>x.id===$('feed').value);chosen=src.id;$('expiry').value=src.data?.expiry||'';$('expiry').readOnly=Boolean(src.data?.expiry);$('strike').value=src.data?.strike||'See exact contract';let rows=src.data?.rows,prev=lastRun?.p;if(prev?.id===src.id){for(let [id,key] of Object.entries({bf:'from',bt:'to',tp:'target',sl:'stop',tr:'trail',slip:'slip',units:'units',lots:'lots',action:'side'}))$(id).value=prev[key];$('et').value=timeOf(prev.entry);$('xt').value=timeOf(prev.exit)}else{$('bf').value=rows?.[0].d||'2026-09-01';$('bt').value=rows?.at(-1).d||end;$('et').value=rows?timeOf(rows[0].m):'09:30';$('xt').value=rows?timeOf(rows.filter(r=>r.d===rows[0].d).at(-1).m):'15:15'}$('coverage').textContent=(rows?src.data.kind+' · CSV · '+src.data.src:'Demo · synthetic minute OHLC')+' · '+(rows?.[0].d||'2026-09-01')+' to '+(rows?.at(-1).d||end);$('results').innerHTML='';$('bp').value=prev?.id===src.id?'Custom':'7D';if($('bp').value!=='Custom')$('bf').value=presetStart($('bt').value,$('bp').value);$('bf').disabled=$('bt').disabled=$('bp').value!=='Custom';if(prev?.id===src.id){$('targetUnit').value=prev.targetUnit||'%';$('stopUnit').value=prev.stopUnit||'%';$('dte').value=prev.dte||'';$('holding').value=prev.holding||'Intraday';$('entryRule').value=prev.rule||'Time only';$('ruleValue').value=prev.ruleValue||0;$('tolerance').value=prev.tolerance??1}}function filterContracts(){
 let isOption=contractMode==='Options';
 $('optionSide').parentElement.hidden=!isOption;$('contractFields').hidden=!isOption;$('expiry').required=isOption;
 let available=sources.filter(x=>isOption?x.data?.kind==='Option contract'&&(x.data.optionType===optionSide||x.s.endsWith(optionSide)):contractMode==='Future'?x.data?.kind==='Future':!['Option contract','Future'].includes(x.data?.kind));
 $('feed').innerHTML=available.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.title)+'</option>').join('');
 let query=$('searchInstrument').value.trim().toUpperCase();available=available.filter(x=>x.title.toUpperCase().includes(query));$('feed').innerHTML=available.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.title)+'</option>').join('');let next=available.find(x=>x.id===chosen)||available.find(x=>x.id==='demo:SENSEX')||available[0];
 $('builder').querySelector('.primary').disabled=!next;
 $('contractNote').textContent=next?'':('Import minute candles for the exact '+(isOption?optionSide:'futures')+' contract to run this backtest.');
 if(isOption&&next)$('contractNote').textContent='Rules evaluate the selected historical contract at entry. Spot, future, delta and indicator rules require matching CSV columns known at the candle open. Positional exits use the next observed session.';if(next){$('feed').value=next.id;sourceChanged()}else{$('results').innerHTML='';$('coverage').textContent='Contract history required';src=null}
}
if(src.data?.kind==='Future')contractMode='Future';if(src.data?.kind==='Option contract'){contractMode='Options';optionSide=(src.data.optionType==='PE'||src.s.endsWith('PE'))?'PE':'CE'}
$('contractMode').value=contractMode;$('optionSide').value=optionSide;
$('contractMode').onchange=()=>{contractMode=$('contractMode').value;filterContracts()};
$('optionSide').onchange=()=>{optionSide=$('optionSide').value;filterContracts()};
$('bp').onchange=()=>{let custom=$('bp').value==='Custom';$('bf').disabled=$('bt').disabled=!custom;if(!custom)$('bf').value=presetStart($('bt').value,$('bp').value)};$('searchInstrument').oninput=()=>{filterContracts();instrumentSearch($('searchInstrument').value)};$('feed').onchange=sourceChanged;filterContracts();$('builder').onsubmit=e=>{e.preventDefault();try{let p={id:src.id,s:src.s,source:src.title,from:$('bf').value,to:$('bt').value,entry:toMin($('et').value),exit:toMin($('xt').value),side:$('action').value};for(let [key,id] of Object.entries({lots:'lots',units:'units',stop:'sl',target:'tp',trail:'tr',slip:'slip'}))p[key]=+$(id).value;Object.assign(p,{mode:contractMode,fees:[...feeSchedule],fee:feeSchedule[0],rate:feeSchedule[2],targetUnit:$('targetUnit').value,stopUnit:$('stopUnit').value,expiry:contractMode==='Options'?$('expiry').value:'',dte:contractMode==='Options'?$('dte').value:''});Object.assign(p,{holding:contractMode==='Options'?$('holding').value:'Intraday',rule:contractMode==='Options'?$('entryRule').value:'Time only',strike:src.data?.strike,ruleValue:+$('ruleValue').value,tolerance:+$('tolerance').value});p.qty=p.lots*p.units;let bars=src.data?.rows||(candleCache[src.id]??=demoBars(src.s));lastRun=simulate(bars,p);lastMonth='';showResults()}catch(err){$('results').innerHTML=empty(esc(err.message))}};if(src&&lastRun?.p.id===src.id)showResults();else if(src&&!src.data)$('builder').requestSubmit()}
function groupByPeriod(trades,weekly){let result=new Map();for(let t of trades){let k=t.d.slice(0,7);if(weekly){let d=new Date(t.d);d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);k=d.toISOString().slice(0,10)}if(!result.has(k))result.set(k,[]);result.get(k).push(t)}return [...result]}
const total=a=>a.reduce((v,t)=>v+t.net,0);
function showResults(){let r=lastRun,t=r.trades;if(!t.length){$('results').innerHTML=empty('No eligible trades. '+r.skipped.length+' incomplete observed sessions. Check the dataset coverage and execution times.');return}
$('results').innerHTML='<section class="panel"><div class="row"><div><div class="ey">'+esc(r.p.source)+'</div><h2>Run performance</h2></div><button onclick="saveDialog()">Save backtest</button></div>'+metrics(runStats(r))+note('Capital uses full entry price × units across open legs. Same-minute entries count before exits. Return is net P&L divided by peak capital.')+note(r.p.from+' through '+r.p.to+' · '+r.skipped.length+' incomplete sessions skipped'+(r.skipped.length?' · '+r.skipped.slice(0,12).join(', '):''))+pnlChart(t,r.prices)+'</section>'+calendarReport(r)+'<section id="daily" class="panel"></section>';drill(lastMonth)}
const tradeHead=['T/ID','Entry date','Entry IST','Instrument','Side','Units','Entry ₹','Capital ₹','Exit date','Exit IST','Exit ₹','Gross ₹','Charges ₹','Net P&L ₹','Return %','Exit reason','Cumulative net ₹'];
function drill(month){
 lastMonth=month;
 const p=lastRun.p,trades=lastRun.trades,byDay=new Map();
 for(const t of trades.filter(t=>t.d.startsWith(month))){
  const day=byDay.get(t.d)||{d:t.d,net:0,value:0};
  day.net+=t.net;day.value+=entryCapital(t,p);day.dd=t.dd;byDay.set(t.d,day);
 }
 const days=[...byDay.values()].sort((a,b)=>b.d.localeCompare(a.d));
 const rows=[...trades].sort(entryOrder).map((t,i)=>{
  const value=entryCapital(t,p);
  return ['T/'+(i+1),t.entryDay||t.d,t.entry,t.s||p.s,t.side||p.side,t.qty??p.qty,t.ep,value,t.d,t.exit,t.xp,t.gross,t.charges,t.net,value?100*t.net/value:0,t.reason,t.cum];
 }).filter(row=>row[8].startsWith(month)).reverse();
 const display=rows.map(row=>row.map((v,i)=>[6,7,10,12].includes(i)?'₹'+fmt(v):[11,13,16].includes(i)?cash(v):i===14?pct(v):esc(String(v))));
 $('daily').innerHTML='<div class="row"><h2>Daily results · '+(month||'All months')+'</h2><button id="allMonths">All months</button></div>'+dayTiles(days)+table(['Session','Net P&L','Return on entry value','Run drawdown'],days.map(t=>[t.d,cash(t.net),pct(t.net/t.value*100),cash(t.dd)]))+'<div class="row" style="margin-top:20px"><h2 id="dailyLog">Transaction order details</h2><button id="texport">Export CSV</button></div>'+table(tradeHead,display);
 $('allMonths').onclick=()=>drill('');
 $('texport').onclick=()=>csv('trades-'+(month||'all'),[tradeHead,...rows]);
}
function saveDialog(){modal('Save backtest','<form id="saveRun"><div class="fields">'+input('Run name','runName',lastRun.p.s+' '+lastRun.p.side+' '+(saved.length+1),'text','maxlength="80"')+'</div><button class="primary">Save to comparison</button><p id="savedMsg"></p></form>');$('saveRun').onsubmit=async e=>{e.preventDefault();try{let item={...lastRun,id:crypto.randomUUID(),name:$('runName').value.trim()};await persist('runs',item);saved.push(item);dlg.close()}catch(err){$('savedMsg').textContent=err.message}}}
function compatible(a,b){return JSON.stringify((a.p.legs||[a.p]).map(l=>l.fees||[]))===JSON.stringify((b.p.legs||[b.p]).map(l=>l.fees||[])) && ['id','from','to','capital','slip','fee','rate'].every(k=>a.p[k]===b.p[k])}
function comparison(){let opts=saved.map((r,i)=>'<option value="'+i+'">'+esc(r.name)+'</option>').join('');$('app').innerHTML=heading('Strategy research','Strategy Comparison','Compare saved runs using the same dataset, dates, fees and slippage.')+'<section class="panel">'+(saved.length?'<div class="fields"><label>Baseline<select id="baseline">'+opts+'</select></label><label>Comparison<select id="candidate"></select></label></div><div id="compareBody"></div>':empty('No saved runs yet. Run a backtest and choose Save backtest.')+'<p><a href="#test">Open Backtester</a></p>')+'</section>';if(!saved.length)return;let render=()=>{let a=saved[+$('baseline').value],b=$('candidate').value===''?null:saved[+$('candidate').value],set=b?[a,b]:[a];$('compareBody').innerHTML=note(esc(a.p.source)+' · '+a.p.from+' to '+a.p.to+' · Slippage '+a.p.slip+' bps · Charges calculated per leg')+table(['Strategy','Return','Net P&L','Drawdown','Trades','Win rate'],set.map(r=>[esc(r.name),pct(peakCapital(r)?100*r.net/peakCapital(r):0),cash(r.net),cash(r.dd),r.trades.length,fmt(r.win)+'%']))+(b?'':empty('Save another run with matching data and execution costs to compare.'))+multiCurve(set)};let options=()=>{let i=+$('baseline').value;$('candidate').innerHTML=saved.map((r,j)=>j!==i&&compatible(saved[i],r)?'<option value="'+j+'">'+esc(r.name)+'</option>':'').join('');render()};$('baseline').onchange=options;$('candidate').onchange=render;options()}
function multiCurve(runs){
 const dates=[...new Set(runs.flatMap(r=>r.trades.map(t=>t.d)))].sort();
 const daily=runs.map(r=>new Map(r.trades.map(t=>[t.d,t.cum]))),values=runs.map(()=>0);
 const rows=dates.map(d=>{daily.forEach((m,i)=>values[i]=m.get(d)??values[i]);return {d,cum:values[0],other:values[1],tip:d+'\n'+runs.map((r,i)=>r.name+' · ₹'+fmt(values[i])).join('\n')}});
 return '<h3>Cumulative net P&L · ₹</h3><div class="legend">'+runs.map((r,i)=>'<span><i class="swatch" style="background:'+(i?'#82bfff':'#ffb157')+'"></i>'+esc(r.name)+'</span>').join('')+'</div>'+plot(rows,'cum','#ffb157',false,runs.length>1?'other':null)
}
